<?php $related=query('SELECT a.* FROM articles a JOIN relations r ON r.related_id=a.id WHERE r.article_id=? AND '.(preview()?"a.status IN ('draft','in_review','published')":"a.status='published'").' LIMIT 3',[$article['id']])->fetchAll();if($related):?><section class="section spacer-bottom"><div class="section-heading"><h2>עוד שאלה שכדאי לבדוק</h2></div><div class="cards"><?php foreach($related as $a)card($a)?></div></section><?php endif?>
